APPLICATION_GUARD = "CREATE OR REPLACE FUNCTION cehub_ai.guard_issue_application() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN\n IF NOT EXISTS (\n  SELECT 1 FROM cehub_ai.ai_issue_event_results r\n  JOIN cehub_ai.agent_runs run ON run.tenant_id=r.tenant_id AND run.id=r.run_id\n  JOIN cehub_project.issues i ON i.tenant_id=r.tenant_id AND i.project_id=r.project_id\n  JOIN cehub_ai.ai_write_policies p ON p.tenant_id=r.tenant_id\n  JOIN cehub_ai.ai_write_scope_revisions s ON s.tenant_id=r.tenant_id AND s.project_id=r.project_id\n  JOIN cehub_event.events e ON e.tenant_id=r.tenant_id AND e.project_id=r.project_id\n  WHERE r.tenant_id=NEW.tenant_id AND r.project_id=NEW.project_id AND r.id=NEW.result_id\n   AND r.run_id=NEW.run_id AND r.model_invocation_id=NEW.model_invocation_id\n   AND r.event_row_id=NEW.source_event_row_id AND r.source_snapshot->>'source_key'=NEW.source_key\n   AND r.source_snapshot=NEW.receipt->'source_snapshot' AND r.proposal=NEW.receipt->'proposal'\n   AND run.status='succeeded' AND run.requested_by_user_id=NEW.requested_by_user_id\n   AND i.id=NEW.issue_id AND i.id::text=NEW.receipt->'issue_snapshot'->>'id'\n   AND p.id=NEW.policy_id AND p.principal_id=NEW.principal_id AND p.mode='tiered'\n   AND p.operation_settings->'event.issue.create'->>'mode' IN ('confirm','automatic')\n   AND s.id=NEW.scope_revision_id AND s.principal_id=NEW.principal_id AND s.enabled\n   AND s.operation_key='event.issue.create'\n   AND e.id=NEW.output_event_row_id AND e.entity_id=NEW.id\n   AND e.event_type='AI_ISSUE_APPLICATION_RECORDED'\n   AND e.payload->>'issue_id'=NEW.issue_id::text AND e.payload->>'disposition'=NEW.disposition\n   AND (\n    (NEW.disposition='reused' AND r.proposal->>'disposition'='reuse_issue'\n     AND r.proposal->>'existing_issue_id'=i.id::text)\n    OR\n    (NEW.disposition='created' AND r.proposal->>'disposition'='create_issue'\n     AND i.created_by_ai_principal_id=NEW.principal_id AND i.reported_by_user_id IS NULL\n     AND i.title=r.proposal->>'title' AND i.description=r.proposal->>'description'\n     AND i.severity=r.proposal->>'severity'\n     AND EXISTS(SELECT 1 FROM cehub_event.events created\n       WHERE created.tenant_id=NEW.tenant_id AND created.project_id=NEW.project_id\n        AND created.id=NEW.issue_event_row_id AND created.entity_id=i.id AND created.event_type='ISSUE_CREATED')\n     AND EXISTS(SELECT 1 FROM cehub_quality.test_cases tc\n       WHERE tc.tenant_id=NEW.tenant_id AND tc.project_id=NEW.project_id AND tc.related_issue_id=i.id\n        AND NEW.source_key='test_case:'||tc.id::text))\n   )\n ) THEN RAISE EXCEPTION 'Issue application requires its exact result, source, writer and business receipt'; END IF;\n\n IF NOT EXISTS(SELECT 1 FROM cehub_event.events e JOIN cehub_audit.audit_log a\n  ON a.tenant_id=e.tenant_id AND a.project_id=e.project_id AND a.event_id=e.event_id\n   AND a.entity=e.entity AND a.entity_id=e.entity_id AND a.timestamp=e.timestamp\n  WHERE e.tenant_id=NEW.tenant_id AND e.project_id=NEW.project_id AND e.id=NEW.output_event_row_id\n   AND e.source='ai_issue_application_service' AND e.entity='ai_issue_application'\n   AND e.entity_id=NEW.id AND e.payload->>'application_id'=NEW.id::text\n   AND a.actor_user_id IS NULL AND a.after_snapshot=NEW.receipt\n   AND a.context->>'origin'='ai' AND a.context->>'writer_principal_id'=NEW.principal_id::text\n   AND a.context->>'requested_by_user_id'=NEW.requested_by_user_id::text\n   AND a.context->>'run_id'=NEW.run_id::text\n   AND a.context->>'result_id'=NEW.result_id::text\n   AND a.context->>'model_invocation_id'=NEW.model_invocation_id::text\n   AND a.context->>'policy_id'=NEW.policy_id::text\n   AND a.context->>'scope_revision_id'=NEW.scope_revision_id::text\n   AND ((NEW.capture_mode='trial' AND a.action='ai_issue.confirmed_apply'\n     AND a.context->>'confirmed_by_user_id'=NEW.confirmed_by_user_id::text)\n    OR (NEW.capture_mode='direct' AND a.action='ai_issue.automatic_apply'\n     AND a.context->'confirmed_by_user_id'='null'::jsonb)))\n THEN RAISE EXCEPTION 'Issue application requires its exact writer audit'; END IF;\n IF NEW.disposition='created' AND NOT EXISTS(\n  SELECT 1 FROM cehub_event.events e JOIN cehub_audit.audit_log a\n   ON a.tenant_id=e.tenant_id AND a.project_id=e.project_id AND a.event_id=e.event_id\n    AND a.entity=e.entity AND a.entity_id=e.entity_id AND a.timestamp=e.timestamp\n  WHERE e.tenant_id=NEW.tenant_id AND e.project_id=NEW.project_id AND e.id=NEW.issue_event_row_id\n   AND e.source='issue_service' AND e.entity='issue' AND e.entity_id=NEW.issue_id\n   AND e.event_type='ISSUE_CREATED' AND a.action='issue.create' AND a.actor_user_id IS NULL\n   AND a.context->>'origin'='ai' AND a.context->>'writer_principal_id'=NEW.principal_id::text\n   AND a.context->>'application_id'=NEW.id::text AND a.context->>'result_id'=NEW.result_id::text\n   AND a.context->>'run_id'=NEW.run_id::text\n   AND a.context->>'model_invocation_id'=NEW.model_invocation_id::text\n   AND a.context->>'source_event_row_id'=NEW.source_event_row_id::text\n   AND a.context->>'requested_by_user_id'=NEW.requested_by_user_id::text\n   AND a.context->>'policy_id'=NEW.policy_id::text AND a.context->>'scope_revision_id'=NEW.scope_revision_id::text\n   AND ((NEW.capture_mode='trial' AND a.context->>'confirmed_by_user_id'=NEW.confirmed_by_user_id::text)\n    OR (NEW.capture_mode='direct' AND a.context->'confirmed_by_user_id'='null'::jsonb\n     AND a.context->'write_execution'=NEW.receipt->'write_receipt')))\n THEN RAISE EXCEPTION 'AI Issue creation requires original application provenance'; END IF;\n IF NEW.capture_mode='direct' THEN\n  IF NOT EXISTS(\n   SELECT 1 FROM cehub_ai.agent_runs run\n   JOIN cehub_ai.ai_write_policies p ON p.tenant_id=run.tenant_id AND p.id=NEW.policy_id\n   JOIN cehub_ai.ai_write_scope_revisions s ON s.tenant_id=run.tenant_id AND s.project_id=run.project_id AND s.id=NEW.scope_revision_id\n   JOIN cehub_ai.ai_issue_trial_protocols protocol ON protocol.tenant_id=run.tenant_id AND protocol.project_id=run.project_id\n   JOIN cehub_ai.ai_issue_trial_collections collection ON collection.tenant_id=protocol.tenant_id\n    AND collection.project_id=protocol.project_id AND collection.protocol_id=protocol.id\n   WHERE run.tenant_id=NEW.tenant_id AND run.project_id=NEW.project_id AND run.id=NEW.run_id\n    AND ((run.run_context->'issue_write_execution')-'application_id')=NEW.receipt->'write_receipt'\n    AND p.operation_settings->'event.issue.create'->>'mode'='automatic'\n    AND NOT EXISTS(SELECT 1 FROM cehub_ai.ai_write_policies later WHERE later.tenant_id=p.tenant_id AND later.revision>p.revision)\n    AND NOT EXISTS(SELECT 1 FROM cehub_ai.ai_write_scope_revisions later WHERE later.tenant_id=s.tenant_id\n      AND later.project_id=s.project_id AND later.operation_key='event.issue.create' AND later.revision>s.revision)\n    AND protocol.id::text=NEW.receipt->'write_receipt'->>'protocol_id'\n    AND protocol.policy_id=NEW.policy_id AND protocol.principal_id=NEW.principal_id\n    AND protocol.scope_revision_id=NEW.scope_revision_id AND protocol.evidence_kind='real_business'\n    AND collection.id::text=NEW.receipt->'write_receipt'->>'collection_id'\n    AND collection.created_at<=NEW.created_at\n    AND NOT EXISTS(SELECT 1 FROM cehub_ai.ai_issue_trial_collections later WHERE later.tenant_id=protocol.tenant_id\n     AND later.project_id=protocol.project_id AND later.protocol_id=protocol.id\n     AND later.created_at<=NEW.created_at AND (later.created_at,later.id)>(collection.created_at,collection.id))\n    AND NEW.receipt->'write_receipt'->'configuration'=protocol.protocol->'configuration'\n    AND NEW.receipt->'write_receipt'->'readiness'->'binding'=protocol.protocol->'binding'\n    AND NEW.receipt->'write_receipt'->'readiness'->'provenance'->'binding'=protocol.protocol->'binding'\n    AND NEW.receipt->'write_receipt'->'readiness'->>'state'='current'\n    AND NEW.receipt->'write_receipt'->'readiness'->'provenance'->'provenance_verified'='true'::jsonb\n    AND NEW.receipt->'write_receipt'->'readiness'->'provenance'->'provider_verified'='true'::jsonb\n    AND NEW.receipt->'write_receipt'->'readiness'->'provenance'->'references'->>'result_id'=NEW.result_id::text\n    AND NEW.receipt->'write_receipt'->'readiness'->'provenance'->'references'->>'invocation_id'=NEW.model_invocation_id::text\n    AND NEW.receipt->'write_receipt'->'readiness'->'qualification_state'->>'protocol_id'=protocol.id::text\n    AND NEW.receipt->'write_receipt'->'readiness'->'qualification_state'->>'latest_collection_id'=collection.id::text\n    AND NEW.receipt->'write_receipt'->'readiness'->'qualification_state'->>'state'='current'\n    AND NEW.receipt->'write_receipt'->'readiness'->'qualification_state'->'original_result'->>'status'='meets_candidate_criteria'\n    AND NEW.receipt->'write_receipt'->'readiness'->'qualification_state'->'fresh_result'->>'status'='meets_candidate_criteria'\n    AND NEW.receipt->'write_receipt'->'monitor'->'stopped'='false'::jsonb\n    AND (NEW.receipt->'write_receipt'->>'checked_at')::timestamptz<=NEW.created_at\n  ) THEN RAISE EXCEPTION 'Automatic Issue requires exact current protocol and qualification originals'; END IF;\n END IF;\n RETURN NEW;\nEND $$;"

OLD_APPLICATION_GUARD = "CREATE OR REPLACE FUNCTION cehub_ai.guard_issue_application() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN\n IF NOT EXISTS (\n  SELECT 1 FROM cehub_ai.ai_issue_event_results r\n  JOIN cehub_ai.agent_runs run ON run.tenant_id=r.tenant_id AND run.id=r.run_id\n  JOIN cehub_project.issues i ON i.tenant_id=r.tenant_id AND i.project_id=r.project_id\n  JOIN cehub_ai.ai_write_policies p ON p.tenant_id=r.tenant_id\n  JOIN cehub_ai.ai_write_scope_revisions s ON s.tenant_id=r.tenant_id AND s.project_id=r.project_id\n  JOIN cehub_event.events e ON e.tenant_id=r.tenant_id AND e.project_id=r.project_id\n  WHERE r.tenant_id=NEW.tenant_id AND r.project_id=NEW.project_id AND r.id=NEW.result_id\n   AND r.run_id=NEW.run_id AND r.model_invocation_id=NEW.model_invocation_id\n   AND r.event_row_id=NEW.source_event_row_id AND r.source_snapshot->>'source_key'=NEW.source_key\n   AND r.source_snapshot=NEW.receipt->'source_snapshot' AND r.proposal=NEW.receipt->'proposal'\n   AND run.status='succeeded' AND run.requested_by_user_id=NEW.requested_by_user_id\n   AND i.id=NEW.issue_id AND i.id::text=NEW.receipt->'issue_snapshot'->>'id'\n   AND p.id=NEW.policy_id AND p.principal_id=NEW.principal_id AND p.mode='tiered'\n   AND p.operation_settings->'event.issue.create'->>'mode' IN ('confirm','automatic')\n   AND s.id=NEW.scope_revision_id AND s.principal_id=NEW.principal_id AND s.enabled\n   AND s.operation_key='event.issue.create'\n   AND e.id=NEW.output_event_row_id AND e.entity_id=NEW.id\n   AND e.event_type='AI_ISSUE_APPLICATION_RECORDED'\n   AND e.payload->>'issue_id'=NEW.issue_id::text AND e.payload->>'disposition'=NEW.disposition\n   AND (\n    (NEW.disposition='reused' AND r.proposal->>'disposition'='reuse_issue'\n     AND r.proposal->>'existing_issue_id'=i.id::text)\n    OR\n    (NEW.disposition='created' AND r.proposal->>'disposition'='create_issue'\n     AND i.created_by_ai_principal_id=NEW.principal_id AND i.reported_by_user_id IS NULL\n     AND i.title=r.proposal->>'title' AND i.description=r.proposal->>'description'\n     AND i.severity=r.proposal->>'severity'\n     AND EXISTS(SELECT 1 FROM cehub_event.events created\n       WHERE created.tenant_id=NEW.tenant_id AND created.project_id=NEW.project_id\n        AND created.id=NEW.issue_event_row_id AND created.entity_id=i.id AND created.event_type='ISSUE_CREATED')\n     AND EXISTS(SELECT 1 FROM cehub_quality.test_cases tc\n       WHERE tc.tenant_id=NEW.tenant_id AND tc.project_id=NEW.project_id AND tc.related_issue_id=i.id\n        AND NEW.source_key='test_case:'||tc.id::text))\n   )\n ) THEN RAISE EXCEPTION 'Issue application requires its exact result, source, writer and business receipt'; END IF;\n RETURN NEW;\nEND $$;"

SAMPLE_GUARD = "\nCREATE FUNCTION cehub_ai.guard_issue_sample_review() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n IF NOT EXISTS(SELECT 1 FROM cehub_ai.ai_issue_applications a JOIN cehub_project.issues i\n  ON i.tenant_id=a.tenant_id AND i.project_id=a.project_id AND i.id=a.issue_id\n  WHERE a.tenant_id=NEW.tenant_id AND a.project_id=NEW.project_id AND a.id=NEW.application_id\n   AND a.issue_id=NEW.issue_id AND a.capture_mode='direct'\n   AND a.receipt->'write_receipt'->'sampled'='true'::jsonb\n   AND i.withdrawn_at IS NULL AND i.updated_at=NEW.issue_updated_at\n   AND NEW.issue_snapshot->>'title'=i.title AND NEW.issue_snapshot->>'status'=i.status\n   AND NEW.issue_snapshot->>'severity'=i.severity\n   AND NEW.issue_snapshot->'description'=to_jsonb(i)->'description')\n THEN RAISE EXCEPTION 'Sample review requires its sampled direct application and current Issue'; END IF;\n IF NEW.version<>(SELECT COALESCE(MAX(version),0)+1 FROM cehub_ai.ai_issue_sample_reviews\n   WHERE tenant_id=NEW.tenant_id AND application_id=NEW.application_id)\n THEN RAISE EXCEPTION 'Sample review must append the next original version'; END IF;\n IF NOT EXISTS(SELECT 1 FROM cehub_event.events e JOIN cehub_audit.audit_log a\n  ON a.tenant_id=e.tenant_id AND a.project_id=e.project_id AND a.event_id=e.event_id\n   AND a.entity=e.entity AND a.entity_id=e.entity_id AND a.timestamp=e.timestamp\n  WHERE e.tenant_id=NEW.tenant_id AND e.project_id=NEW.project_id AND e.id=NEW.output_event_row_id\n   AND e.entity='ai_issue_sample_review' AND e.entity_id=NEW.id\n   AND e.event_type='AI_ISSUE_SAMPLE_REVIEWED' AND e.source='ai_issue_sample_service'\n   AND e.payload->>'review_id'=NEW.id::text AND e.payload->>'application_id'=NEW.application_id::text\n   AND e.payload->>'issue_id'=NEW.issue_id::text AND e.payload->>'verdict'=NEW.verdict\n   AND a.actor_user_id=NEW.actor_user_id AND a.action='ai_issue.sample_review'\n   AND a.after_snapshot->>'review_id'=NEW.id::text AND a.after_snapshot->>'version'=NEW.version::text\n   AND a.after_snapshot->>'reason'=NEW.reason AND a.after_snapshot->>'verdict'=NEW.verdict\n   AND a.after_snapshot->>'issue_digest'=NEW.issue_digest AND a.after_snapshot->'issue_snapshot'=NEW.issue_snapshot)\n THEN RAISE EXCEPTION 'Sample review requires its original named event and audit'; END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER guard_issue_sample_review BEFORE INSERT ON cehub_ai.ai_issue_sample_reviews\n FOR EACH ROW EXECUTE FUNCTION cehub_ai.guard_issue_sample_review();\nCREATE TRIGGER immutable_issue_sample_review BEFORE UPDATE OR DELETE ON cehub_ai.ai_issue_sample_reviews\n FOR EACH ROW EXECUTE FUNCTION cehub_ai.protect_checkpoint_history();\nREVOKE ALL ON cehub_ai.ai_issue_sample_reviews FROM PUBLIC;\nDO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='pdos_agent') THEN\n REVOKE ALL ON cehub_ai.ai_issue_sample_reviews FROM pdos_agent; END IF; END $$;\n"


def _shape(table: str, expression: str) -> None:
    op.execute(f"ALTER TABLE cehub_ai.{table} DROP CONSTRAINT ck_{table}_shape")
    op.execute(f"ALTER TABLE cehub_ai.{table} ADD CONSTRAINT ck_{table}_shape CHECK ({expression})")


def upgrade() -> None:
    op.execute("ALTER TABLE cehub_ai.ai_issue_applications ALTER COLUMN confirmed_by_user_id DROP NOT NULL")
    _shape("ai_issue_applications", NEW_APPLICATION_SHAPE)
    _shape("ai_write_runtime_stops", NEW_STOP_SHAPE)
    op.execute(DDL)
    op.execute(APPLICATION_GUARD)
    op.execute(SAMPLE_GUARD)


def downgrade() -> None:
    op.execute("""DO $$ BEGIN IF EXISTS(SELECT 1 FROM cehub_ai.ai_issue_sample_reviews)
     OR EXISTS(SELECT 1 FROM cehub_ai.ai_issue_applications WHERE capture_mode='direct')
     OR EXISTS(SELECT 1 FROM cehub_ai.ai_write_runtime_stops WHERE operation_key='event.issue.create')
     THEN RAISE EXCEPTION 'Retain automatic Issue, sample and runtime stop history'; END IF; END $$;""")
    op.execute("DROP TABLE cehub_ai.ai_issue_sample_reviews")
    op.execute("DROP FUNCTION cehub_ai.guard_issue_sample_review()")
    op.execute(OLD_APPLICATION_GUARD)
    _shape("ai_issue_applications", OLD_APPLICATION_SHAPE)
    op.execute("ALTER TABLE cehub_ai.ai_issue_applications ALTER COLUMN confirmed_by_user_id SET NOT NULL")
    _shape("ai_write_runtime_stops", OLD_STOP_SHAPE)
